const item = $input.first().json;

const subject = item.subject || '';
const from = item.from || item.sender || '';
const rawText = item.textPlain || item.textHtml || item.snippet || '';
const createdAt = item.date || new Date().toISOString();

const message = rawText
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const text = `${subject}\n${from}\n${message}`;
const lower = text.toLowerCase();

const emailMatch = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
const email = emailMatch ? emailMatch[0].toLowerCase() : '';

const phoneMatch = text.match(/(?:\+?\d[\d\s().-]{7,}\d)/);
const phone = phoneMatch ? phoneMatch[0].replace(/\s+/g, ' ').trim() : '';

let name = '';
const fromNameMatch = from.match(/^\"?([^\"<]+)\"?\s*</);
if (fromNameMatch) name = fromNameMatch[1].trim();
const nameMatch = message.match(/(?:name|full name)\s*[:\-]\s*([^,|\n\r]+)/i);
if (nameMatch) name = nameMatch[1].trim();
if (!name && email) {
  name = email.split('@')[0].replace(/[._-]+/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
}

const buyerWords = ['buy', 'buyer', 'purchase', 'looking for', 'viewing', 'mortgage'];
const sellerWords = ['sell', 'seller', 'valuation', 'appraisal', 'list my', 'listing'];
const rentalWords = ['rent', 'rental', 'lease', 'tenant'];
const urgentWords = ['urgent', 'asap', 'today', 'tomorrow', 'this week', 'immediately', 'ready', 'cash'];
const highIntentWords = ['viewing', 'book', 'call', 'appointment', 'offer', 'pre-approved', 'preapproved', 'valuation'];

const matched = [];
for (const word of [...buyerWords, ...sellerWords, ...rentalWords, ...urgentWords, ...highIntentWords]) {
  if (lower.includes(word)) matched.push(word);
}

let leadType = 'General Inquiry';
const buyerHits = buyerWords.filter(w => lower.includes(w)).length;
const sellerHits = sellerWords.filter(w => lower.includes(w)).length;
const rentalHits = rentalWords.filter(w => lower.includes(w)).length;
if (sellerHits >= buyerHits && sellerHits >= rentalHits && sellerHits > 0) leadType = 'Seller';
else if (buyerHits >= rentalHits && buyerHits > 0) leadType = 'Buyer';
else if (rentalHits > 0) leadType = 'Rental';

const propertyTypes = ['apartment', 'house', 'villa', 'plot', 'land', 'office', 'shop', 'commercial', 'condo'];
const propertyType = propertyTypes.find(type => lower.includes(type)) || 'Not specified';

const budgetMatch = text.match(/(?:budget|price|range)\s*[:\-]?\s*([A-Z]{0,3}\s?[$â‚¬Â£]?[\d,.]+(?:\s?(?:k|m|million|lakh|crore))?\s?(?:-|to)?\s?[$â‚¬Â£]?[\d,.]*(?:\s?(?:k|m|million|lakh|crore))?)/i)
  || text.match(/([$â‚¬Â£]\s?[\d,.]+(?:\s?(?:k|m|million))?)/i);
const budget = budgetMatch ? budgetMatch[1].trim() : 'Not specified';

const timeframeMatch = text.match(/(?:move|buy|sell|rent|timeline|timeframe|when)\s*[:\-]?\s*(today|tomorrow|this week|this month|next month|within \d+ days|within \d+ weeks|within \d+ months)/i);
const timeframe = timeframeMatch ? timeframeMatch[1] : (urgentWords.some(w => lower.includes(w)) ? 'Urgent' : 'Not specified');

const locationMatch = text.match(/(?:location|area|city|neighborhood|neighbourhood)\s*[:\-]\s*([^,|\n\r]+)/i);
const location = locationMatch ? locationMatch[1].trim() : 'Not specified';

let leadScore = 20;
if (email) leadScore += 10;
if (phone) leadScore += 15;
if (leadType !== 'General Inquiry') leadScore += 15;
if (propertyType !== 'Not specified') leadScore += 10;
if (budget !== 'Not specified') leadScore += 10;
leadScore += urgentWords.filter(w => lower.includes(w)).length * 15;
leadScore += highIntentWords.filter(w => lower.includes(w)).length * 12;
leadScore = Math.min(100, leadScore);

let leadPriority = 'Cold';
if (leadScore >= 75) leadPriority = 'Hot';
else if (leadScore >= 50) leadPriority = 'Warm';

const now = new Date();
const followUp = new Date(now);
if (leadPriority === 'Hot') followUp.setHours(now.getHours() + 2);
else if (leadPriority === 'Warm') followUp.setDate(now.getDate() + 1);
else followUp.setDate(now.getDate() + 3);

let recommendedAction = 'Review lead and decide whether to follow up.';
if (leadPriority === 'Hot') recommendedAction = 'Call or reply within 2 hours.';
else if (leadPriority === 'Warm') recommendedAction = 'Follow up within 1 business day.';
else recommendedAction = 'Add to nurture list and follow up within 3 days.';

return [{
  json: {
    createdAt,
    name,
    email,
    phone,
    leadType,
    propertyType,
    location,
    budget,
    timeframe,
    leadScore,
    leadPriority,
    matchedKeywords: [...new Set(matched)].join(', '),
    followUpDue: followUp.toISOString(),
    recommendedAction,
    subject,
    message: message.slice(0, 1400),
    source: 'Gmail real estate inquiry'
  }
}];
